:root {
   --font-weight: normal;/*⁣‍‌‌⁠‍‍⁠​​‌⁠​‌​​⁠⁠⁠‍‍⁠​​⁠⁠⁠​‍‌‌⁠⁠‍‌‌​‍⁠⁠​⁠‌⁠​‍⁠‌⁠‌‌​‍​‌‌‍‌⁠​‌‍‍‌​⁣ 🍓字体粗细，粗是bold，细是light */

   /* === 顶部导航栏（通透磨砂） === */
   --chat-header-bg: rgba(240, 240, 240, 0.72);
   --chat-header-border: 0.5px solid rgba(0, 0, 0, 0.08);
   --chat-header-title-color: #000;
   --chat-header-title-size: 16px;
   --chat-header-title-weight: 600;
   --chat-header-subtitle-color: #8e8e8e;
   --chat-header-subtitle-size: 12px;
   --chat-header-icon-color: #171717;

   /* 🌞 白天：未读胶囊 */
   --unread-bg: rgba(180, 180, 180, 0.45);
   --unread-color: #151515;

   /* 🌞 白天：时间戳/系统消息/旁白（实心微透浅灰底，柔和干净不发暗） */
   --timestamp-color: #555555;
   --date-divider-color: #555555;
   --narration-color: #555555;
   --system-msg-color: #555555;
   --na-bg: rgba(235, 237, 240, 0.85); /* 👈 实心偏灰微透 */
   --na-bd: none;

   /* 🌞 白天：独立引用条（同款温和浅灰底） */
   --reply-detached-bg: rgba(235, 237, 240, 0.85); /* 👈 同步改为微透实心灰 */
   --reply-detached-radius: 5px;
   --reply-detached-padding: 6px 10px;
   --reply-detached-border: none;
   --reply-detached-text-color: #555555;
   --reply-detached-name-color: #555555;

   /* === 微信同款回复预览栏 === */
   --reply-bar-accent: transparent;
   --reply-bar-bg: #DCDDDA;
   --reply-bar-radius: 6px;
   --reply-bar-padding: 6px 10px;
   --reply-bar-margin-bottom: 2px;
   --reply-bar-margin-top: 6px;
   --reply-bar-text-color: #666666;
   --reply-bar-accent-border: none;

   /* === 翻译内容 === */
   --translation-size: 14px;
   --translation-text-color: #515151;
   --translation-line-height: 1.2;
   --translation-padding: 10px 0 0 0;
   --translation-bg: transparent;
   --translation-radius: 0;
